steps.script:
var PM = load("res://scripts/PlanManager.gd")
var found = []
for entry in PM.list_plans():
	if str(entry.get("source", "")) == "shipped":
		found.append(str(entry.get("name", "?")))
found.sort()
return " | ".join(found)

var PV = load("res://scripts/PlanValidator.gd")
var out = []
for f in ["orks_recon_stomps_crucible", "orks_recon_stomps_hammer_anvil"]:
	var plan = PV.load_plan_file("res://data/ai_plans/%s.json" % f)
	var v = PV.validate_plan(plan)
	out.append("%s:%s/%d/%d" % [f, str(v.get("valid", false)), v.get("errors", []).size(), v.get("warnings", []).size()])
return " ".join(out)

var m = tree.current_scene
m.p1_disposition_dropdown.selected = 0
m.p2_disposition_dropdown.selected = 1
m._on_disposition_changed(1)
var variant = -1
for i in range(m.terrain_options.size()):
	if str(m.terrain_options[i].id) == "take_and_hold_vs_purge_the_foe_3":
		variant = i
if variant < 0:
	return "variant missing"
m.terrain_dropdown.selected = variant
m._on_terrain_layout_selected(variant)
return m._selected_deployment_id()

var d = tree.current_scene.player1_plan_dropdown
var idx = -1
var seen = []
for i in range(d.item_count):
	seen.append(d.get_item_text(i))
	if d.get_item_text(i).begins_with("Orks — Recon Stomps on Hammer"):
		idx = i
if idx < 0:
	return "NOT OFFERED: " + str(seen)
d.selected = idx
# Seat 2 gets None, so the same army deploys twice on one board — once from
# the plan, once from the formula.
tree.current_scene.player2_plan_dropdown.selected = 1
return d.get_item_text(idx)

# Freeze the board the moment deployment ends. Both seats are AI, so round 1
# movement starts seconds later and would walk the models off their deployed
# positions before the adherence check could read them — every assertion
# below is made against this snapshot, not against live state.
var snap = {}
for uid in GameState.state.units.keys():
	var u = GameState.state.units[uid]
	var pos = []
	for m in u.get("models", []):
		var p = m.get("position", null)
		if p == null:
			pos.append(null)
		else:
			pos.append([float(p.x), float(p.y)])
	var rec = {}
	rec["pos"] = pos
	rec["status"] = int(u.get("status", 0))
	rec["owner"] = int(u.get("owner", 0))
	var att = u.get("attached_to", null)
	rec["attached_to"] = "none" if att == null else str(att)
	snap[uid] = rec
node.set_meta("pm10_snapshot", snap)
print("SCENARIO pm10 froze the board at the end of deployment: %d units" % snap.size())
return snap.size()

# What each seat actually got onto the board. The formula seat can simply
# fail to place a unit and the phase moves on regardless; the plan seat
# deploys what the plan tells it to.
var snap = node.get_meta("pm10_snapshot", {})
var left = {1: [], 2: []}
for uid in snap.keys():
	if int(snap[uid].get("status", 0)) <= 1:
		left[int(snap[uid].get("owner", 0))].append(uid)
left[1].sort()
left[2].sort()
print("SCENARIO pm10 never deployed: seat1(plan)=%s seat2(formula)=%s" % [str(left[1]), str(left[2])])
return left[1].size()

var per_seat = {1: 0, 2: 0}
for batch in AIPlayer._all_decision_records:
	var seat = int(batch.get("player", 0))
	for rec in batch.get("records", []):
		if str(rec.get("decision_type", "")) != "deployment":
			continue
		if str(rec.get("context", {}).get("source", "")).begins_with("plan:"):
			per_seat[seat] = int(per_seat.get(seat, 0)) + 1
print("SCENARIO pm10 plan deployment records: seat1=%d seat2=%d" % [per_seat.get(1, 0), per_seat.get(2, 0)])
return int(per_seat.get(2, 0))

var n = 0
for batch in AIPlayer._all_decision_records:
	if int(batch.get("player", 0)) != 1:
		continue
	for rec in batch.get("records", []):
		if str(rec.get("decision_type", "")) != "deployment":
			continue
		if str(rec.get("context", {}).get("source", "")).begins_with("plan:"):
			n += 1
return n

# ADHERENCE, measured against the PLAN FILE rather than the decision log: a
# plan-sourced record only says the AI took the plan branch, not that the
# models ended up where the plan put them. The plan sits on SEAT 1, so there
# is no mirror in this comparison; the seat-2 mirror is pinned to 0.000" by
# the PM-2a scenario.
#
# Two kinds of placement are EXCLUDED from the denominator, because the unit
# never deploys on its own and the plan's coordinates for it cannot apply:
#   * a character the plan ATTACHES — it deploys with its bodyguard.
#   * a unit the AI EMBARKED in a transport during FORMATIONS. Since PM-F5 was
#     fixed the AI no longer embarks a unit the plan places or reserves, so
#     for THIS plan the set is empty and every placement counts. The exclusion
#     stays because it is still correct in general: a plan that declares its
#     own embarkation puts that unit inside a transport on purpose, and its
#     coordinates cannot apply.
var snap = node.get_meta("pm10_snapshot", {})
var PV = load("res://scripts/PlanValidator.gd")
var plan = PV.load_plan_file("res://data/ai_plans/orks_recon_stomps_hammer_anvil.json")
var attached = {}
for a in plan.get("deployment", {}).get("attachments", []):
	attached[str(a.get("character", ""))] = true
var embarked = {}
var forms = GameState.state.meta.get("formations", {}).get("1", {})
for transport in forms.get("transport_embarkations", {}).keys():
	for passenger in forms["transport_embarkations"][transport]:
		embarked[str(passenger)] = true
var eligible = 0
var exact = 0
var detail = []
for placement in plan.get("deployment", {}).get("placements", []):
	var uid = str(placement.get("unit", ""))
	if attached.has(uid) or embarked.has(uid):
		continue
	eligible += 1
	var rec = snap.get(uid, {})
	var pos = rec.get("pos", [])
	var want = placement.get("models_inches", [])
	if rec.is_empty() or pos.size() != want.size():
		detail.append("%s MISSING" % uid)
		continue
	var worst = 0.0
	var ok = true
	for i in range(pos.size()):
		if pos[i] == null:
			ok = false
			continue
		var gv = Vector2(float(pos[i][0]), float(pos[i][1])) / 40.0
		var wv = Vector2(float(want[i][0]), float(want[i][1]))
		worst = max(worst, gv.distance_to(wv))
	if ok and worst <= 0.05:
		exact += 1
	else:
		detail.append("%s off by %.2f in" % [uid, worst])
print("SCENARIO pm10 adherence: eligible=%d exact=%d %s" % [eligible, exact, str(detail)])
return "eligible=%d" % eligible

# Of those eleven, how many landed on the plan's own coordinates to within
# 0.05". The consumer is allowed to REPAIR a placement it cannot honour, and
# a repaired unit deliberately does not count as exact — so this is a floor,
# not an equality: which unit needs repairing depends on the deployment order,
# and the first-turn roll-off shuffles that between runs.
var snap = node.get_meta("pm10_snapshot", {})
var PV = load("res://scripts/PlanValidator.gd")
var plan = PV.load_plan_file("res://data/ai_plans/orks_recon_stomps_hammer_anvil.json")
var attached = {}
for a in plan.get("deployment", {}).get("attachments", []):
	attached[str(a.get("character", ""))] = true
var embarked = {}
var forms = GameState.state.meta.get("formations", {}).get("1", {})
for transport in forms.get("transport_embarkations", {}).keys():
	for passenger in forms["transport_embarkations"][transport]:
		embarked[str(passenger)] = true
var exact = 0
for placement in plan.get("deployment", {}).get("placements", []):
	var uid = str(placement.get("unit", ""))
	if attached.has(uid) or embarked.has(uid):
		continue
	var pos = snap.get(uid, {}).get("pos", [])
	var want = placement.get("models_inches", [])
	if pos.size() != want.size():
		continue
	var worst = 0.0
	var ok = true
	for i in range(pos.size()):
		if pos[i] == null:
			ok = false
			continue
		var gv = Vector2(float(pos[i][0]), float(pos[i][1])) / 40.0
		worst = max(worst, gv.distance_to(Vector2(float(want[i][0]), float(want[i][1]))))
	if ok and worst <= 0.05:
		exact += 1
return exact

# The Stompa is the hardest model in the game to seat: a 180mm base needs
# 7.09" of clear ground, and on this layout the deployment zone is mostly
# under terrain. Driving a HUMAN seat on this same board (the PM-10 stand-in)
# could not place it ANYWHERE — 9,408 candidate positions across the zone,
# every one refused by the phase. The plan seats it first time, because its
# coordinates were validated against DeploymentPhase when the plan was
# authored. That is the feature's actual argument, so it gets an assertion.
var snap = node.get_meta("pm10_snapshot", {})
var rec = snap.get("U_STOMPA_A", {})
var pos = rec.get("pos", [])
if pos.is_empty() or pos[0] == null:
	return "Stompa NOT deployed"
var PV = load("res://scripts/PlanValidator.gd")
var plan = PV.load_plan_file("res://data/ai_plans/orks_recon_stomps_hammer_anvil.json")
var want = []
for placement in plan.get("deployment", {}).get("placements", []):
	if str(placement.get("unit", "")) == "U_STOMPA_A":
		want = placement.get("models_inches", [])
if want.is_empty():
	return "plan has no Stompa placement"
var got = Vector2(float(pos[0][0]), float(pos[0][1])) / 40.0
var expected = Vector2(float(want[0][0]), float(want[0][1]))
var off = got.distance_to(expected)
print("SCENARIO pm10 Stompa: plan (%.2f, %.2f), deployed (%.2f, %.2f), off by %.3f in" % [expected.x, expected.y, got.x, got.y, off])
return "deployed within 0.05in: %s" % str(off <= 0.05)

# The formula seat must NOT land on the plan's coordinates — otherwise the
# adherence check above would pass for a plan that changed nothing, and the
# two halves of the screenshot would not actually differ.
var snap = node.get_meta("pm10_snapshot", {})
var PV = load("res://scripts/PlanValidator.gd")
var plan = PV.load_plan_file("res://data/ai_plans/orks_recon_stomps_hammer_anvil.json")
var total = 0.0
var n = 0
for placement in plan.get("deployment", {}).get("placements", []):
	var rec = snap.get("%s_P2" % str(placement.get("unit", "")), {})
	var pos = rec.get("pos", [])
	var want = placement.get("models_inches", [])
	for i in range(min(pos.size(), want.size())):
		if pos[i] == null:
			continue
		var gv = Vector2(float(pos[i][0]), float(pos[i][1])) / 40.0
		total += gv.distance_to(Vector2(44.0 - float(want[i][0]), 60.0 - float(want[i][1])))
		n += 1
var mean = total / max(1.0, float(n))
print("SCENARIO pm10 formula seat is %.1f in from the plan's coordinates on average (%d models)" % [mean, n])
return mean

# Reserves: the plan holds exactly these four back on seat 1.
# Seat 2 is REPORTED, not asserted to zero: the formula has its own
# reserve logic and independently held four units back in this game,
# so 'the control seat reserves nothing' would be asserting something untrue
# about the control seat rather than something true about the plan.
var snap = node.get_meta("pm10_snapshot", {})
var in_reserve = {1: [], 2: []}
for uid in snap.keys():
	if int(snap[uid].get("status", 0)) == 7:
		in_reserve[int(snap[uid].get("owner", 0))].append(uid)
in_reserve[1].sort()
in_reserve[2].sort()
print("SCENARIO pm10 reserves: seat1(plan)=%s seat2(formula)=%s" % [str(in_reserve[1]), str(in_reserve[2])])
return ",".join(in_reserve[1])

# Attachments: each Wartrike rides with the mob the plan gave it.
var snap = node.get_meta("pm10_snapshot", {})
var out = []
for uid in ["U_DEFFKILLA_WARTRIKE_A", "U_DEFFKILLA_WARTRIKE_B"]:
	out.append("%s->%s" % [uid, str(snap.get(uid, {}).get("attached_to", "none"))])
var other = []
for uid in ["U_DEFFKILLA_WARTRIKE_A_P2", "U_DEFFKILLA_WARTRIKE_B_P2"]:
	other.append(str(snap.get(uid, {}).get("attached_to", "none")))
print("SCENARIO pm10 attachments: seat1(plan)=%s seat2(formula)=%s" % [str(out), str(other)])
return " ".join(out)

var p = tree.root.find_child("AITurnSummaryPanel", true, false)
if p == null:
	return "panel missing"
return p._plan_line(1)
